const input = $input.first().json;
const body = input.body || input;
const owner = body.owner || $env.GITHUB_OWNER || '';
let repos = [];
try {
  const raw = body.repos || $env.GITHUB_REPOS || '[]';
  repos = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) { repos = []; }
if (!owner) throw new Error('GITHUB_OWNER가 설정되지 않았습니다.');

// 이번 주 월요일 00:00 ~ 현재 (UTC)
const now = new Date();
const dayOfWeek = now.getUTCDay(); // 0=Sun, 1=Mon ... 6=Sat
const daysFromMonday = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
const monday = new Date(now);
monday.setUTCDate(now.getUTCDate() - daysFromMonday);
monday.setUTCHours(0, 0, 0, 0);

const since = monday.toISOString();
const until = now.toISOString();

return [{ json: { owner, repos, since, until } }];

// GitHub API 응답 평탄화 + GITHUB_REPOS 필터링 + 1 repo per item 변환
const initItem = $('Init Params').first().json;
const filterList = initItem.repos || [];

const allItems = $input.all();
let repoList = [];
for (const item of allItems) {
  if (Array.isArray(item.json)) {
    repoList = repoList.concat(item.json);
  } else if (item.json && item.json.name) {
    repoList.push(item.json);
  }
}

const filtered = filterList.length > 0
  ? repoList.filter(r => filterList.includes(r.name))
  : repoList;

if (filtered.length === 0) {
  throw new Error(`분석 대상 Repo 없음. filter=${JSON.stringify(filterList)}, 전체=${repoList.length}개`);
}

return filtered.map(r => ({
  json: {
    owner: initItem.owner,
    repo: r.name,
    full_name: r.full_name,
    since: initItem.since,
    until: initItem.until
  }
}));

// GET Root Contents 응답에서 파일 목록 추출
const fileData = $input.all();

let fileNames = [];
let full_name = '';
let repo = '';

for (const item of fileData) {
  if (Array.isArray(item.json)) {
    for (const f of item.json) {
      if (f.name) fileNames.push(f.name);
      if (!full_name && f.url) {
        const m = f.url.match(/repos\/([^/]+\/[^/]+)\/contents/);
        if (m) { full_name = m[1]; repo = full_name.split('/')[1]; }
      }
    }
  } else if (item.json && item.json.name) {
    fileNames.push(item.json.name);
    if (!full_name && item.json.url) {
      const m = item.json.url.match(/repos\/([^/]+\/[^/]+)\/contents/);
      if (m) { full_name = m[1]; repo = full_name.split('/')[1]; }
    }
  }
}

// fallback
if (!full_name) {
  const fallback = $('Loop Over Repos').first().json;
  full_name = fallback.full_name || '';
  repo = fallback.repo || '';
}

const loopData = $('Loop Over Repos').first().json;
return [{
  json: {
    owner: loopData.owner || full_name.split('/')[0],
    repo,
    full_name,
    since: loopData.since,
    until: loopData.until,
    file_names: fileNames
  }
}];

// Commit 집계: commit_count, active_days, commit_messages
const allItems = $input.all();
let commits = [];
for (const item of allItems) {
  if (Array.isArray(item.json)) commits = commits.concat(item.json);
  else if (item.json && item.json.sha) commits.push(item.json);
}

const commitMessages = commits.map(c => c.commit?.message?.split('\n')[0] || '').filter(Boolean).slice(0, 30);
const activeDaySet = new Set(
  commits.map(c => (c.commit?.author?.date || c.commit?.committer?.date || '').substring(0, 10)).filter(Boolean)
);

// 평일만 카운트 (0=Sun, 6=Sat 제외)
const weekdaySet = new Set(
  [...activeDaySet].filter(d => {
    const day = new Date(d).getUTCDay();
    return day >= 1 && day <= 5;
  })
);

const repoInfo = $('Attach Repo Info').first().json;

return [{ json: {
  _repoCtx: {
    owner: repoInfo.owner,
    repo: repoInfo.repo,
    full_name: repoInfo.full_name,
    since: repoInfo.since,
    until: repoInfo.until,
    file_names: repoInfo.file_names
  },
  commit_count: commits.length,
  active_days: weekdaySet.size,
  commit_messages: commitMessages
} }];

// PR 집계: 이번 주 merged_at 기준 필터
const allItems = $input.all();
let prs = [];
for (const item of allItems) {
  if (Array.isArray(item.json)) prs = prs.concat(item.json);
  else if (item.json && item.json.number) prs.push(item.json);
}

const commitData = $('Aggregate Commits').first().json;
const since = commitData._repoCtx?.since || '';
const sinceDate = since ? new Date(since) : new Date(0);

const mergedThisWeek = prs.filter(pr =>
  pr.merged_at && new Date(pr.merged_at) >= sinceDate
);

return [{ json: {
  _repoCtx: commitData._repoCtx,
  commit_count: commitData.commit_count,
  active_days: commitData.active_days,
  commit_messages: commitData.commit_messages,
  merged_pr_count: mergedThisWeek.length,
  merged_prs: mergedThisWeek.map(pr => ({
    number: pr.number,
    title: pr.title,
    merged_at: pr.merged_at,
    user: pr.user?.login || null
  })).slice(0, 20)
} }];

// Commit 집계 + PR 집계 합산 → Loop로 복귀
const items = $input.all();
let commitData = null;
let prData = null;

for (const item of items) {
  if (item.json.merged_pr_count !== undefined) prData = item.json;
  else if (item.json.commit_count !== undefined && item.json.merged_pr_count === undefined) commitData = item.json;
}
// Merge 노드는 두 입력을 순서대로 출력 — 첫 번째가 Aggregate Commits
if (!commitData && items[0]) commitData = items[0].json;
if (!prData && items[1]) prData = items[1].json;

const ctx = (commitData || prData)?._repoCtx || {};

return [{ json: {
  owner: ctx.owner,
  repo: ctx.repo,
  full_name: ctx.full_name,
  since: ctx.since,
  until: ctx.until,
  file_names: ctx.file_names || [],
  commit_count: commitData?.commit_count ?? 0,
  active_days: commitData?.active_days ?? 0,
  commit_messages: commitData?.commit_messages ?? [],
  merged_pr_count: prData?.merged_pr_count ?? 0,
  merged_prs: prData?.merged_prs ?? []
} }];

// 루트 파일 패턴으로 Repo 유형 분류 (5단계 우선순위)
const items = $input.all();
const classified = [];
const commitStatsByRepo = {};

for (const item of items) {
  const { repo, file_names, commit_count, active_days, commit_messages, merged_pr_count, merged_prs } = item.json;
  const fileSet = new Set(file_names || []);
  const fileArr = file_names || [];

  let type = 'unknown';
  let reason = '';

  if (fileSet.has('Podfile') || fileSet.has('pubspec.yaml') || fileSet.has('Package.swift')) {
    type = 'mobile';
    reason = fileSet.has('Podfile') ? 'Podfile' : fileSet.has('pubspec.yaml') ? 'pubspec.yaml' : 'Package.swift';
  } else if (fileSet.has('build.gradle') && !fileSet.has('package.json')) {
    type = 'mobile'; reason = 'build.gradle';
  } else if (fileArr.some(f => f.endsWith('.tf')) || fileSet.has('helmfile.yaml') || fileSet.has('terraform') || fileSet.has('k8s') || fileSet.has('infra')) {
    type = 'config';
    reason = fileArr.find(f => f.endsWith('.tf')) || 'helmfile/k8s/terraform';
  } else if (fileSet.has('pom.xml') || fileSet.has('requirements.txt') || fileSet.has('go.mod') || fileSet.has('Cargo.toml') || fileSet.has('build.sbt') || (fileSet.has('package.json') && (fileSet.has('nest-cli.json') || fileSet.has('server.js') || fileSet.has('app.js') || fileSet.has('index.js')))) {
    type = 'backend';
    reason = fileSet.has('pom.xml') ? 'pom.xml' : fileSet.has('requirements.txt') ? 'requirements.txt' : fileSet.has('go.mod') ? 'go.mod' : fileSet.has('Cargo.toml') ? 'Cargo.toml' : 'package.json+server entry';
  } else if (fileSet.has('package.json') && (fileSet.has('next.config.js') || fileSet.has('next.config.ts') || fileSet.has('vite.config.ts') || fileSet.has('vite.config.js') || fileSet.has('angular.json') || fileSet.has('vue.config.js') || fileSet.has('nuxt.config.ts') || fileSet.has('svelte.config.js'))) {
    type = 'frontend';
    reason = fileSet.has('next.config.js') || fileSet.has('next.config.ts') ? 'Next.js' : fileSet.has('vite.config.ts') || fileSet.has('vite.config.js') ? 'Vite' : fileSet.has('angular.json') ? 'Angular' : 'Vue/Nuxt/Svelte';
  } else if (fileSet.has('package.json')) {
    type = 'frontend'; reason = 'package.json (fallback)';
  }

  classified.push({ repo, type, reason });
  commitStatsByRepo[repo] = {
    commit_count: commit_count || 0,
    active_days: active_days || 0,
    commit_messages: commit_messages || [],
    merged_pr_count: merged_pr_count || 0,
    merged_prs: merged_prs || []
  };
}

const result = { backend: [], frontend: [], config: [], mobile: [], unknown: [] };
for (const item of classified) result[item.type].push(item.repo);

// 전체 commit 집계 (WBS-ORK에서 진척률 계산용)
const allCommitMessages = Object.values(commitStatsByRepo)
  .flatMap(s => s.commit_messages);
const totalCommits = Object.values(commitStatsByRepo)
  .reduce((acc, s) => acc + s.commit_count, 0);
const maxActiveDays = Object.values(commitStatsByRepo)
  .reduce((acc, s) => Math.max(acc, s.active_days), 0);

return [{ json: {
  ...result,
  _classified_detail: classified,
  commit_stats: commitStatsByRepo,
  total_commit_count: totalCommits,
  max_active_days: maxActiveDays,
  all_commit_messages: allCommitMessages.slice(0, 50)
} }];

const resp = $input.item.json;
const headers = resp.headers || {};
const remaining = parseInt(headers['x-ratelimit-remaining'] ?? headers['X-RateLimit-Remaining'] ?? '5000', 10);
const limit = parseInt(headers['x-ratelimit-limit'] ?? headers['X-RateLimit-Limit'] ?? '5000', 10);
const usedPct = limit > 0 ? Math.round((1 - remaining / limit) * 100) : 0;
const repos = Array.isArray(resp.body) ? resp.body : (resp.body || []);
return [{ json: { repos, rate_limit: { remaining, limit, used_pct: usedPct }, rate_limit_warning: usedPct >= 80 } }];
